package main

import (
	"encoding/json"
	"github.com/jackc/pgx/v5"
	"net/http"
	"time"
)

// Registration is resumable using a random installation secret generated by the App.
// A send key can only write content; it cannot read history or replace device tokens.
func (a *App) registerDevice(w http.ResponseWriter, r *http.Request) error {
	var b struct {
		Name         string `json:"device_name"`
		Platform     string `json:"platform"`
		Registration string `json:"registration_token"`
	}
	if e := decode(r, &b); e != nil {
		return e
	}
	name, nameError := cleanDeviceName(b.Name)
	if nameError != nil {
		return nameError
	}
	b.Name = name
	if b.Platform != "ios" || len(b.Registration) != 64 || !tokenValid(b.Registration) {
		return bad("invalid_registration", "设备注册信息无效。")
	}
	ctx := r.Context()
	tx, e := a.db.Begin(ctx)
	if e != nil {
		return e
	}
	defer tx.Rollback(ctx)
	if e = txLock(ctx, tx, "registration:"+hash(b.Registration)); e != nil {
		return e
	}
	var sealed []byte
	var revoked bool
	e = tx.QueryRow(ctx, `SELECT k.secret,d.revoked FROM device_keys k JOIN devices d ON d.id=k.device_id WHERE k.registration_hash=$1`, hash(b.Registration)).Scan(&sealed, &revoked)
	if e == nil {
		if revoked {
			return unauthorized()
		}
		raw, e := a.unseal(sealed)
		if e != nil {
			return e
		}
		ok(w, json.RawMessage(raw))
		return nil
	}
	if e != pgx.ErrNoRows {
		return e
	}
	var admin string
	if e = tx.QueryRow(ctx, "SELECT id FROM users WHERE username=$1", a.cfg.Username).Scan(&admin); e != nil {
		return e
	}
	// Bound anonymous registrations on a private server. Resuming is allowed at the limit.
	if e = txLock(ctx, tx, "registration-limit:"+admin); e != nil {
		return e
	}
	var n int
	if e = tx.QueryRow(ctx, "SELECT count(*) FROM device_keys k JOIN devices d ON d.id=k.device_id WHERE owner_id=$1 AND NOT d.revoked", admin).Scan(&n); e != nil {
		return e
	}
	if n >= 200 {
		return bad("device_limit", "服务器设备数量已达上限。")
	}
	user, device, dt, rt, sk := id("acct_"), id("dev_"), token(), token(), token()
	until := time.Now().Add(3650 * 24 * time.Hour)
	// Each automatically registered installation owns its own data namespace.
	if _, e = tx.Exec(ctx, "INSERT INTO users(id,username,password) VALUES($1,$2,$3)", user, "device:"+device, []byte{}); e != nil {
		return e
	}
	if _, e = tx.Exec(ctx, "INSERT INTO devices(id,user_id,name,platform) VALUES($1,$2,$3,'ios')", device, user, b.Name); e != nil {
		return e
	}
	for kind, t := range map[string]string{"device": dt, "read": rt, "delivery": sk} {
		if _, e = tx.Exec(ctx, "INSERT INTO credentials(hash,user_id,device_id,kind,expires_at) VALUES($1,$2,$3,$4,$5)", hash(t), user, device, kind, until); e != nil {
			return e
		}
	}
	result := map[string]any{"server_id": a.cfg.ID, "account_id": user, "binding_id": device, "device_token": dt, "read_token": rt, "send_key": sk, "expires_at": stamp(until)}
	sealed, e = a.seal(canonical(result))
	if e != nil {
		return e
	}
	if _, e = tx.Exec(ctx, "INSERT INTO device_keys(device_id,owner_id,registration_hash,secret) VALUES($1,$2,$3,$4)", device, admin, hash(b.Registration), sealed); e != nil {
		return e
	}
	if e = tx.Commit(ctx); e != nil {
		return e
	}
	ok(w, result)
	return nil
}

// The Web session owns this server's registered devices. A device credential only
// authorizes its own installation; its name or a supplied account ID never grants access.
func (a *App) webDevice(r *http.Request, p identity, device string) (identity, error) {
	var user string
	e := a.db.QueryRow(r.Context(), `SELECT d.user_id FROM devices d LEFT JOIN device_keys k ON k.device_id=d.id WHERE d.id=$1 AND NOT d.revoked AND (d.user_id=$2 OR k.owner_id=$2)`, device, p.User).Scan(&user)
	if e == pgx.ErrNoRows {
		return p, notfound()
	}
	if e != nil {
		return p, e
	}
	p.User = user
	p.Device = device
	return p, nil
}

func (a *App) deviceAccess(w http.ResponseWriter, r *http.Request) error {
	p, e := a.authenticate(r, "device", "web")
	if e != nil {
		return e
	}
	device := r.PathValue("id")
	if p.Kind == "web" {
		if device == "" {
			return notfound()
		}
		p, e = a.webDevice(r, p, device)
		if e != nil {
			return e
		}
	} else if device != "" {
		return notfound()
	}
	ctx := r.Context()
	tx, e := a.db.Begin(ctx)
	if e != nil {
		return e
	}
	defer tx.Rollback(ctx)
	// Also lock the device row so concurrent revoke cannot leave a live replacement key.
	var owner string
	if e = tx.QueryRow(ctx, "SELECT user_id FROM devices WHERE id=$1 AND NOT revoked FOR UPDATE", p.Device).Scan(&owner); e != nil {
		return unauthorized()
	}
	var sealed []byte
	e = tx.QueryRow(ctx, "SELECT secret FROM device_keys WHERE device_id=$1", p.Device).Scan(&sealed)
	var data map[string]any
	if e == nil {
		raw, err := a.unseal(sealed)
		if err != nil {
			return err
		}
		if err = json.Unmarshal(raw, &data); err != nil {
			return err
		}
	} else if e == pgx.ErrNoRows {
		// Compatible upgrade for installations paired by an older App: keep IDs and cards.
		sk := token()
		data = map[string]any{"send_key": sk}
		sealed, e = a.seal(canonical(data))
		if e != nil {
			return e
		}
		if _, e = tx.Exec(ctx, "INSERT INTO credentials(hash,user_id,device_id,kind,expires_at) VALUES($1,$2,$3,'delivery',now()+interval '10 years')", hash(sk), owner, p.Device); e != nil {
			return e
		}
		if _, e = tx.Exec(ctx, "INSERT INTO device_keys(device_id,owner_id,secret) VALUES($1,$2,$3)", p.Device, owner, sealed); e != nil {
			return e
		}
	} else {
		return e
	}
	if e = tx.Commit(ctx); e != nil {
		return e
	}
	sk, valid := data["send_key"].(string)
	if !valid {
		return bad("invalid_access", "设备发送地址不可用。")
	}
	ok(w, map[string]any{"send_key": sk, "message_url": a.cfg.PublicURL + "/v1/push/" + sk, "state_url": a.cfg.PublicURL + "/v1/state/" + sk + "/{data_id}"})
	return nil
}

func (a *App) keyedMessage(w http.ResponseWriter, r *http.Request) error {
	return a.withSendKey(w, r, a.message)
}
func (a *App) keyedState(w http.ResponseWriter, r *http.Request) error {
	return a.withSendKey(w, r, a.state)
}
func (a *App) withSendKey(w http.ResponseWriter, r *http.Request, f endpoint) error {
	key := r.PathValue("key")
	if len(key) != 64 || !tokenValid(key) {
		return unauthorized()
	}
	req := r.Clone(r.Context())
	req.Header.Set("Authorization", "Bearer "+key)
	p, e := a.authenticate(req, "delivery", "channel")
	if e != nil {
		return e
	}
	// Authentication above restricts URL-based requests to send-only keys.
	_ = p
	return f(w, req)
}
